/**
 * Model-facing `generate_video` tool over `ctx.video` and `ctx.attachments`: send the
 * text prompt to the reserved provider, durably commit the generated bytes as a verbatim
 * file attachment, and return the file handle beside a bounded text envelope. The tool
 * returns an actionable "video unavailable" answer — without failing the session — when
 * no provider is mounted or no attachment store can commit the bytes. It runtime-injects
 * only `tools`, `video`, and `systemPrompt` and imports no provider.
 *
 * Namespace plugin (named exports, no default export).
 * @module @deepseek-ai/dsh-tool-video
 */

import type { Context } from '@deepseek-ai/cordis'
import z from '@deepseek-ai/schemastery'
import { defineTool } from '@deepseek-ai/dsh-tools'
import type { ToolExecution } from '@deepseek-ai/dsh-tools'
import { AttachmentId } from '@deepseek-ai/dsh-attachment'
import type { AttachmentStore, FileAttachmentRef } from '@deepseek-ai/dsh-attachment'
import type { ContentBlock } from '@deepseek-ai/dsh-llm'
import { VideoError } from '@deepseek-ai/dsh-video'
import { MAX_TIMER_DELAY_MS } from '@deepseek-ai/dsh-timeout'
import {
  DEFAULT_MAX_RESULT_CHARS,
  formatGeneratedVideo,
  parseGenerateVideoArgs,
  presentGenerateVideoCall,
} from './render.ts'

export {
  DEFAULT_MAX_RESULT_CHARS,
  formatGeneratedVideo,
  parseGenerateVideoArgs,
  presentGenerateVideoCall,
  UNAVAILABLE_TEXT,
} from './render.ts'
export type { GenerateVideoArgs, GeneratedVideoItem } from './render.ts'

/** Cordis plugin name for loader diagnostics. */
export const name = 'tool-video'

/** Services required by this plugin. */
export const inject = ['tools', 'video', 'systemPrompt']

/** Default tool-call timeout budget (ms), covering one generation round trip. */
export const DEFAULT_VIDEO_TOOL_TIMEOUT_MS = 660_000

/** The stable system-prompt guidance positioning the generation tool and its optionality. */
export const VIDEO_PROMPT_TEXT =
  'Use generate_video to create a video from a text prompt. It is unavailable until a video provider is configured — then continue without video generation, for example by suggesting the user configure one.'

/** Plugin configuration: the result cap and the timeout budget. */
export interface Config {
  /** Largest complete rendered result in characters, including truncation metadata (default 8000). */
  maxResultChars?: number
  /** Tool-call timeout budget in ms (default 660000). */
  timeoutMs?: number
}

export const Config: z<Config> = z.object({
  maxResultChars: z.number().default(DEFAULT_MAX_RESULT_CHARS),
  timeoutMs: z.number().max(MAX_TIMER_DELAY_MS).default(DEFAULT_VIDEO_TOOL_TIMEOUT_MS),
})

type ResolvedConfig = Required<Config>

/** The structured video metadata projected into the tool's output schema. */
export interface GeneratedVideoValue {
  attachmentId: string
  name: string
  bytes: number
  mediaType: string
}

/** The structured outcome declared by the `generate_video` output schema. */
export interface GenerateVideoValue {
  status: 'ok' | 'unavailable'
  video?: GeneratedVideoValue
}

/**
 * Re-brand a structured video outcome into the durable attachment reference a
 * `FileBlock` carries.
 * @param video - the video metadata from the output schema.
 * @returns the branded attachment reference.
 */
export function fileRefFromValue(video: GeneratedVideoValue): FileAttachmentRef {
  return {
    attachmentId: AttachmentId(video.attachmentId),
    name: video.name,
    bytes: video.bytes,
  }
}

/**
 * Project one structured generation outcome into its model-facing envelope and file handle.
 * @param value - the generation outcome.
 * @returns the content blocks used by native and nested dispatches.
 */
export function generateVideoContent(value: GenerateVideoValue): ContentBlock[] {
  const blocks: ContentBlock[] = [{ type: 'text', text: formatGeneratedVideo(value, DEFAULT_MAX_RESULT_CHARS) }]
  if (value.status === 'ok' && value.video !== undefined) {
    blocks.push({ type: 'file', attachment: fileRefFromValue(value.video) })
  }
  return blocks
}

/**
 * Register the `generate_video` tool and its system-prompt guidance.
 * @param ctx - the plugin context (must inject `tools`, `video`, `systemPrompt`).
 * @param config - the resolved plugin configuration.
 */
export function apply(ctx: Context, config: Config): void {
  const resolved = config as ResolvedConfig
  assertPositiveInteger('maxResultChars', resolved.maxResultChars)
  assertTimer('timeoutMs', resolved.timeoutMs)

  ctx.systemPrompt.section({
    name: 'tool:video',
    order: ctx.systemPrompt.getSectionOrder('TOOL_VIDEO'),
    text: VIDEO_PROMPT_TEXT,
  })

  ctx.tools.register(defineTool({
    name: 'generate_video',
    description:
      'Generate a video from a text prompt and return the video file. prompt is required; size is an optional refinement such as "1280x720", duration is an optional length in seconds, aspectRatio is an optional hint such as "16:9" or "adaptive", and firstFrame, lastFrame, referenceImage, referenceVideo, and referenceAudio are optional publicly reachable URLs of frame-conditioning and reference media the provider may use to guide the generation. Returns an actionable unavailable message when no video provider is configured.',
    parameters: {
      prompt: { type: 'string', required: true, description: 'The text prompt describing the video to generate.' },
      size: { type: 'string', description: 'Optional requested video size (for example "1280x720" or "720x1280"); the provider interprets the hint.' },
      duration: { type: 'integer', description: 'Optional requested duration in seconds; the provider interprets the hint.' },
      referenceImage: { type: 'string', description: 'Optional publicly reachable URL of one reference image guiding the generation (image-to-video); a provider that does not accept reference media ignores it.' },
      referenceVideo: { type: 'string', description: 'Optional publicly reachable URL of one reference video guiding the generation (video-to-video); a provider that does not accept reference media ignores it.' },
      firstFrame: { type: 'string', description: 'Optional publicly reachable URL of one image conditioning the video\'s first frame; a provider that does not accept frame conditioning ignores it.' },
      lastFrame: { type: 'string', description: 'Optional publicly reachable URL of one image conditioning the video\'s last frame; a provider that does not accept frame conditioning ignores it.' },
      referenceAudio: { type: 'string', description: 'Optional publicly reachable URL of one reference audio guiding the generation (audio-to-video); a provider that does not accept reference media ignores it.' },
      aspectRatio: { type: 'string', description: 'Optional requested aspect ratio (for example "16:9", "9:16", or "adaptive"); the provider interprets the hint.' },
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          status: { type: 'string', required: true, enum: ['ok', 'unavailable'] },
          video: {
            type: 'object',
            additionalProperties: false,
            properties: {
              attachmentId: { type: 'string', required: true },
              name: { type: 'string', required: true },
              bytes: { type: 'integer', required: true },
              mediaType: { type: 'string', required: true },
            },
          },
        },
      },
      render: (_args, value) => generateVideoContent(value),
      // Persist only the prompt-facing facts. The attachment reference is NOT
      // copied here: the settled `content` already carries the file block with
      // the complete reference, mirroring `read_image`'s single-record rule.
      presentationMeta: (_args, value) => ({
        ...value.status === 'ok' && value.video !== undefined ? { mediaType: value.video.mediaType } : {},
      }),
    },
    timeoutMs: resolved.timeoutMs,
    // Content-addressed attachment writes are idempotent and the generation is
    // stateless, so concurrent calls cannot conflict.
    isConcurrencySafe: () => true,
    async execute(args, exec: ToolExecution) {
      const input = parseGenerateVideoArgs(args)
      // Gate before any generation I/O so a refusal never spends the caller's
      // provider budget on bytes the deployment cannot durably commit.
      if (ctx.get('attachments') === undefined) {
        return { status: 'unavailable' as const }
      }
      try {
        const result = await ctx.video.generate({
          prompt: input.prompt,
          ...input.size === undefined ? {} : { size: input.size },
          ...input.duration === undefined ? {} : { duration: input.duration },
          ...input.referenceImage === undefined ? {} : { referenceImage: input.referenceImage },
          ...input.referenceVideo === undefined ? {} : { referenceVideo: input.referenceVideo },
          ...input.firstFrame === undefined ? {} : { firstFrame: input.firstFrame },
          ...input.lastFrame === undefined ? {} : { lastFrame: input.lastFrame },
          ...input.referenceAudio === undefined ? {} : { referenceAudio: input.referenceAudio },
          ...input.aspectRatio === undefined ? {} : { aspectRatio: input.aspectRatio },
        }, exec.signal)
        // Persist before returning: the file block must reference a durably
        // committed object by the time the tool/result event is appended.
        const attachments = ctx.get('attachments') as AttachmentStore
        const ref = await saveGeneratedVideo(attachments, result.data, result.mediaType)
        return {
          status: 'ok' as const,
          video: {
            attachmentId: ref.attachmentId,
            name: ref.name,
            bytes: ref.bytes,
            mediaType: result.mediaType,
          },
        }
      } catch (error) {
        if (error instanceof VideoError && error.code === 'VIDEO_UNAVAILABLE') {
          return { status: 'unavailable' as const }
        }
        throw error
      }
    },
    presentCall: presentGenerateVideoCall,
  }))
}

/** Download media types this deployment stores, mapped to the durable name's extension. */
const VIDEO_MEDIA_TYPE_EXTENSIONS: Record<string, string> = {
  'video/mp4': 'mp4',
  'video/webm': 'webm',
  'video/quicktime': 'mov',
}

/**
 * Commit one generated video into the durable attachment store under a stable name.
 * @param attachments - the mounted attachment store.
 * @param data - the generated video bytes.
 * @param mediaType - the media type the bytes decode as.
 * @returns the durable attachment reference.
 * @throws an actionable error when the endpoint's media type is not storable.
 */
async function saveGeneratedVideo(attachments: AttachmentStore, data: Uint8Array, mediaType: string): Promise<FileAttachmentRef> {
  const extension = VIDEO_MEDIA_TYPE_EXTENSIONS[mediaType]
  if (extension === undefined) {
    throw new Error(`the generation endpoint returned a "${mediaType}" video, which this deployment cannot store; configure an endpoint that returns MP4/WebM/MOV videos`)
  }
  return attachments.saveFile({ data, name: `generated.${extension}` })
}

/** Reject a non-positive-integer config value at load, so misconfiguration fails loud. */
function assertPositiveInteger(name: string, value: number): void {
  if (!Number.isInteger(value) || value < 1) {
    throw new Error(`tool-video: ${name} must be a positive integer`)
  }
}

/** Reject a timer value Node would clamp instead of scheduling as configured. */
function assertTimer(name: string, value: number): void {
  if (!Number.isInteger(value) || value < 1 || value > MAX_TIMER_DELAY_MS) {
    throw new Error(`tool-video: ${name} must be a positive integer no greater than ${MAX_TIMER_DELAY_MS}`)
  }
}
